//! 🔺️ move-material leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfMaterial;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::move_material::mutation::{apply, validate, GltfMoveMaterialPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{materials_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.move-material.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfMoveMaterialOperation { Insert { position: usize, item: GltfMaterial }, Delete { index: usize, removed: GltfMaterial }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfMoveMaterialDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfMoveMaterialPayload, pub operation: GltfMoveMaterialOperation }
fn operation(payload: &GltfMoveMaterialPayload, base: &GltfSnapshot) -> GltfMoveMaterialOperation { GltfMoveMaterialOperation::Move { index: payload.index, position: payload.position } }
fn touched_paths(payload: &GltfMoveMaterialPayload) -> Vec<String> { vec![format!("document/materials/{}", payload.index), format!("document/materials/{}", payload.position)] }
pub fn validate_diff(diff: &GltfMoveMaterialDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfMoveMaterialDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfMoveMaterialOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Materials, &Change::Insert(*position))?; next.document.materials.insert(*position, item.clone());  }, GltfMoveMaterialOperation::Delete { index, .. } => { materials_op(&mut next, GltfTopLevelFamily::Materials, *index, None, None)?;  }, GltfMoveMaterialOperation::Move { index, position } => { materials_op(&mut next, GltfTopLevelFamily::Materials, *index, Some(*position), None)?;  }, GltfMoveMaterialOperation::Reorder { order } => { materials_op(&mut next, GltfTopLevelFamily::Materials, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfMoveMaterialDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfMoveMaterialPayload, base: &GltfSnapshot) -> Result<GltfMoveMaterialDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfMoveMaterialDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfMoveMaterialPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Materials, base, &next)) }
